code.Python3:
# Time:  O(n)
# Space: O(1)

# bit manipulation
class Solution(object):
    def minOperations(self, nums, k):
        """
        :type nums: List[int]
        :type k: int
        :rtype: int
        """
        def popcount(x):
            return bin(x).count('1')

        return popcount(reduce(lambda x, y: x^y, nums, k))

